import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,D as n,E as r,M as i,N as a,O as o,P as s,T as c,b as l,j as u,k as d,l as f,n as p,o as m,p as h,t as g,v as _}from"./shared-pB8LFUv2.js";import{t as v}from"./git-branch--KUP4I0u.js";import{t as y}from"./settings-2-CL2ulZKB.js";import{t as b}from"./CodeEditor-BZlrvoTL.js";var x=e(),S=`Глава 4 · Блок 13 · Организация и зрелые механизмы FastAPI`;function C({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{variant:`project`,chip:e??S,title:`Общие настройки`,intro:`Соберём параметры запуска в одном проверенном объекте. API получит из него имя FastAPI и путь к данным, а CLI применит те же правила выбора JSON и сохранит привычный заголовок меню.`,tags:[{icon:(0,x.jsx)(y,{size:14}),label:`Settings как данные`},{icon:(0,x.jsx)(v,{size:14}),label:`одна граница сборки`}]}),(0,x.jsxs)(s,{number:`00`,title:`Точка старта → Новый вопрос → Результат`,children:[(0,x.jsx)(o,{children:`В нашем Planner есть API и CLI, а задачи уже сохраняются через один JsonStorage. JSON_PATH и APP_NAME приходят в программу как строки окружения. Файл .env становится источником только после явной загрузки; значение процесса имеет приоритет. Теперь соберём эти значения в общую проверенную конфигурацию.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`API и CLI уже работают с одним Planner; теперь мы согласуем путь к JSON для обоих запусков, а имя зададим приложению FastAPI.`},{title:`Новый вопрос`,description:`Как проверить настройки обоих запусков и при этом сохранить привычное имя в меню CLI?`},{title:`Результат`,description:`Мы проверим общие правила JSON_PATH; FastAPI использует app_name, а меню CLI оставит фиксированную подпись.`}]}),(0,x.jsx)(`p`,{children:`Маршрут идёт от двух значений к их явной проверке, затем к использованию на границе запуска и к изолированной регрессии. Мы не меняем формат задачи, HTTP-контракт или само хранилище.`})]}),(0,x.jsxs)(s,{number:`01`,title:`Два запуска не должны по-разному понимать конфигурацию`,children:[(0,x.jsx)(o,{children:`API и CLI остаются двумя входами в один Planner. Если каждый сам читает JSON_PATH и придумывает собственные правила, одна команда может открыть один файл, а другая другой.`}),(0,x.jsx)(`p`,{children:`Представим две кассы одного магазина. Им не нужно копировать каталог товаров и независимо решать, какая цена действует: им нужна одна согласованная карточка правил. Так же API и CLI получают общий путь к JSON, а FastAPI дополнительно использует проверенное имя приложения.`}),(0,x.jsx)(g,{caption:`Внутри каждого запуска настройки проверяются до создания приложения и сервиса`,children:(0,x.jsxs)(m,{label:`Путь от строк окружения к точке запуска`,children:[(0,x.jsx)(f,{title:`Среда процесса`,shape:`input-output`,children:(0,x.jsx)(`p`,{children:`JSON_PATH и APP_NAME приходят строками`})}),(0,x.jsx)(p,{label:`прочитать и проверить`}),(0,x.jsx)(f,{title:`load_settings`,children:(0,x.jsx)(`p`,{children:`Различает default, пустое значение и ошибку`})}),(0,x.jsx)(p,{label:`собранные значения`}),(0,x.jsx)(f,{title:`Settings`,children:(0,x.jsx)(`p`,{children:`json_path: Path и app_name: str`})}),(0,x.jsx)(p,{label:`передать при запуске`}),(0,x.jsx)(f,{title:`API или CLI`,shape:`terminator`,children:(0,x.jsx)(`p`,{children:`Общий путь к JSON; app_name использует API`})})]})}),(0,x.jsx)(`p`,{children:`Схема показывает один процесс за раз. API и CLI не делят объект между процессами: каждый запуск создаёт свой Settings и проверяет значения по общим правилам. Оба используют json_path для выбора файла, а app_name меняет заголовок FastAPI.`}),(0,x.jsx)(`p`,{children:`Общий объект не означает, что обе точки запуска используют каждое поле. API передаёт app_name в FastAPI при создании приложения, а API и CLI используют json_path при выборе JSON-storage. CLI проверяет app_name вместе с остальными полями Settings, но не выводит его в меню. Если передать готовый Settings на границе, обработчики и команды не читают os.environ сами; тесты тоже могут задать значения явно.`}),(0,x.jsx)(r,{tone:`info`,children:`Настройки описывают запуск приложения. Они не являются полями Task, параметрами HTTP-запроса или отдельным сервисом.`})]}),(0,x.jsxs)(s,{number:`02`,title:`Settings хранит значения, а не проверяет их автоматически`,children:[(0,x.jsx)(o,{children:`Знакомая dataclass подходит как небольшой контейнер. Она задаёт, какие значения собраны вместе, но сама не читает окружение и не решает, допустима ли пустая строка или путь к каталогу.`}),(0,x.jsx)(b,{caption:`форма объекта`,code:`from dataclasses import dataclass
from pathlib import Path

@dataclass
class Settings:
    json_path: Path
    app_name: str`}),(0,x.jsx)(`p`,{children:`Аннотация json_path: Path не превращает строку из окружения в Path и не проверяет, указывает ли путь на файл. Мы делаем эти шаги явно до создания Settings. Это похоже на карточку поездки: карточка хранит пункт назначения и имя пассажира, но сама не сверяет адрес и не выбирает маршрут. Граница аналогии проста: карточка помогает увидеть набор данных, а реальная проверка всё равно принадлежит отдельной функции.`}),(0,x.jsx)(`p`,{children:`load_settings отвечает за переход от исходных строк к готовым значениям. Сначала функция получает строки, затем отличает отсутствие от пустого ввода, выполняет преобразования и проверяет правила. Только после этого она возвращает Settings. Такая граница позволяет тестировать правила отдельно от FastAPI.`}),(0,x.jsx)(h,{prompt:`Сопоставим каждую часть с её настоящей ролью. Ошибка здесь обычно возникает, когда мы ждём от контейнера автоматической проверки.`,leftTitle:`Часть`,rightTitle:`Ответственность`,pairs:[{left:`dataclass Settings`,right:`Форма собранных значений`},{left:`load_settings()`,right:`Читает, преобразует и проверяет`},{left:`FastAPI`,right:`Использует готовую конфигурацию при запуске`},{left:`HTTP schema`,right:`Проверяет данные отдельного запроса`}],explanation:`Settings хранит уже подготовленные значения. Проверки выполняются до его использования, а HTTP-схема отвечает за другой слой данных.`}),(0,x.jsx)(r,{tone:`info`,children:`Обычная dataclass не является BaseSettings и не загружает .env. Источник строки и проверка значения остаются явными частями нашей программы.`})]}),(0,x.jsxs)(s,{number:`03`,title:`Отсутствие, пустое значение и путь означают разное`,children:[(0,x.jsx)(o,{children:`Если переменной нет, мы можем применить прежний default. Если переменная есть, но содержит пустую строку, это уже явный ввод с ошибкой. Нельзя склеивать эти ситуации одной проверкой truthiness.`}),(0,x.jsx)(b,{caption:`Фрагмент: сначала различаем None и пустую строку`,code:`raw_name = environment.get("APP_NAME")

if raw_name is None:
    app_name = "StudyHub Planner"
elif not raw_name.strip():
    raise ValueError("APP_NAME must not be empty")
else:
    app_name = raw_name`}),(0,x.jsx)(`p`,{children:`При отсутствии APP_NAME мы сохраняем прежнее имя StudyHub Planner. Явно заданная пустая строка не означает «вернуться к default»: запуск должен остановиться с понятной ошибкой. То же правило относится к пустому JSON_PATH. Это как различие между незаполненной графой, для которой действует правило по умолчанию, и заполненной графой, значение которой оказалось неверным.`}),(0,x.jsx)(`p`,{children:`Путь тоже требует правила. Path("data/tasks.json") остаётся относительным к текущей рабочей папке. Если API запущено из корня, а CLI из другой папки, одинаковая строка может привести к разным файлам. Мы связываем относительный путь с корнем проекта; абсолютный путь сохраняет своё значение.`}),(0,x.jsx)(`p`,{children:`Корнем здесь служит корень проекта, а не папка, из которой вызвана команда. После привязки относительный путь становится устойчивым между запусками. Отсутствующий файл допустим: JsonStorage создаст его при успешной записи. Папка вместо файла означает другую ситуацию: её мы отклоняем до сборки storage.`}),(0,x.jsx)(`p`,{children:`Следующий код сокращён до нужного шага: environment уже содержит прочитанные строки, а project_root указывает на корень StudyHub. По строкам видно, когда выбирается default и почему относительный путь привязывается к проекту.`}),(0,x.jsx)(_,{code:`raw_path = environment.get("JSON_PATH")
if raw_path is None:
    raw_path = "data/tasks.json"
path = Path(raw_path)
if not path.is_absolute():
    path = project_root / path`,steps:[{line:0,note:`Получаем строку. В этом примере переменная отсутствует.`,vars:{raw_path:`None`}},{line:1,note:`Проверяем именно отсутствие, а не любое ложное значение.`,vars:{raw_path:`None`}},{line:2,note:`Подставляем прежний путь только для отсутствующей переменной.`,vars:{raw_path:`"data/tasks.json"`}},{line:3,note:`Строим объект Path. Пока он относительный.`,vars:{path:`Path("data/tasks.json")`}},{line:4,note:`Условие подтверждает, что у пути ещё нет корня диска или файловой системы.`,vars:{"absolute?":`False`}},{line:5,note:`Прикрепляем путь к корню проекта, а не к случайному cwd.`,vars:{path:`project_root / data/tasks.json`}}]}),(0,x.jsx)(`p`,{children:`После разрешения пути мы проверяем, не указывает ли уже существующий путь на каталог. Каталог нельзя передать JsonStorage как файл задач. При этом отсутствие самого файла допустимо: хранилище может создать его при первой записи. Ошибка конфигурации должна возникнуть до записи и не переключать приложение на другой JSON.`}),(0,x.jsx)(r,{tone:`info`,children:`Новый процесс читает окружение заново. Внутри одного запуска настройки готовятся один раз; автоматическое обновление и кэширование в этом занятии не вводятся.`})]}),(0,x.jsxs)(s,{number:`04`,title:`Ошибка конфигурации не является HTTP 422`,children:[(0,x.jsx)(o,{children:`Неверный JSON_PATH мешает собрать приложение. HTTP 422 появляется, когда уже работающий API получил запрос с неподходящими данными. Это разные моменты и разные причины отказа.`}),(0,x.jsx)(`p`,{children:`Если API не удалось настроить, мы не должны создавать новый файл задач в случайном месте или отвечать 422 как будто пользователь прислал неверное поле. Сборка должна завершиться до старта обработчиков. Когда приложение уже работает, прежняя проверка тела запроса продолжает возвращать свой статус и сохраняет контракт.`}),(0,x.jsx)(`p`,{children:`Порядок помогает найти место сбоя: сначала читаем значения, затем создаём Settings, затем storage и сервис, и только потом запускаем API. Невалидный HTTP-body появляется позже, уже внутри работающего приложения. Мы не смешиваем две ошибки общим fallback и не отправляем пользователю конфигурационную проблему как будто он неверно заполнил задачу.`}),(0,x.jsx)(t,{code:`raw_path = environment.get("JSON_PATH") or "data/tasks.json"
storage = JsonStorage(Path(raw_path))`,question:`Какой ввод эта запись ошибочно превращает в default?`,options:[`Только отсутствующий JSON_PATH`,`И отсутствующий, и явно пустой JSON_PATH`,`Ни один: or проверяет только None`],correctIndex:1,explanation:`Пустая строка тоже ложная, поэтому or скрывает явную ошибку конфигурации. Мы выбираем default только при raw_path is None, а пустое значение отклоняем до создания JsonStorage.`,fix:`raw_path = environment.get("JSON_PATH")
if raw_path is None:
    raw_path = DEFAULT_JSON_PATH
elif not raw_path.strip():
    raise ValueError("JSON_PATH must not be empty")`}),(0,x.jsx)(l,{question:`Приложение уже собрано. Запрос содержит неверное поле Task. Какой слой отвечает за отказ?`,options:[`Конфигурация запуска должна завершить процесс`,`Схема запроса проверяет вход и API сохраняет прежний HTTP-ответ`,`CLI выбирает новый JSON-файл`],correctIndex:1,explanation:`Настройки проверяются на старте. Ошибка конкретного HTTP-ввода остаётся валидацией запроса и не меняет путь к хранилищу.`})]}),(0,x.jsxs)(s,{number:`05`,title:`Одна проверенная конфигурация входит в сборку`,children:[(0,x.jsx)(o,{children:`Когда настройки готовы, их передают точке запуска. Мы не читаем окружение в каждом endpoint и не создаём вторую копию Planner для CLI.`}),(0,x.jsx)(`p`,{children:`В API собранные настройки доступны рядом с уже созданным сервисом: app.state.settings хранит конфигурацию, а app.state.planner продолжает хранить готовый PlannerService. Эти значения отвечают за разные вещи. Настройки не заменяют сервис, а сервис не должен повторно угадывать путь.`}),(0,x.jsx)(`p`,{children:`CLI использует тот же загрузчик Settings и те же проверки, но остаётся обычным интерфейсом командной строки. Он берёт json_path для хранилища, не обращается к app.state и не использует FastAPI Depends. Функция show_menu по-прежнему выводит фиксированную подпись StudyHub Planner: APP_NAME влияет на заголовок FastAPI, а не на меню CLI.`}),(0,x.jsx)(c,{question:`Какой вариант не даёт обработчикам и интерфейсам расходиться?`,left:{title:`Проверить при запуске`,code:`settings = load_settings()
service = build_service(settings=settings)`,note:`Обе точки запуска получают значения после одних проверок.`},right:{title:`Читать в каждой точке`,code:`# Фрагмент app/api.py
api_path = os.environ.get("JSON_PATH")
# Фрагмент app/main.py
cli_path = os.environ.get("JSON_PATH")`,note:`Правила и default могут незаметно разойтись.`},preferred:`left`,explanation:`Мы готовим объект на границе запуска, затем передаём его туда, где он нужен. Это не создаёт нового пути хранения и не вмешивается в работу запроса.`}),(0,x.jsx)(`p`,{children:`Представим диспетчера, который перед сменой выдаёт проверенный маршрутный лист. Водитель не вычисляет адрес заново на каждой остановке. Так и приложение получает конфигурацию при запуске, а обработчик использует готовое состояние. Следующий процесс снова прочитает свои значения, поэтому это не глобальный вечный объект.`}),(0,x.jsx)(r,{tone:`info`,children:`build_service остаётся единственной точкой создания Planner и JsonStorage. Если тест передал собственный storage, сборка сохраняет именно этот объект, а не подменяет его путём из рабочей среды.`}),(0,x.jsx)(`p`,{children:`Обычный API-run собирает Settings один раз, передаёт app_name в FastAPI и сохраняет объект в app.state.settings. Готовый PlannerService остаётся в app.state.planner, поэтому существующие роуты и /stats продолжают обращаться к тому же сервису. CLI вызывает ту же загрузку на старте и использует json_path, сохраняя фиксированную подпись show_menu.`})]}),(0,x.jsxs)(s,{number:`06`,title:`Проверяем настройки отдельно и сохраняем прежнее поведение`,children:[(0,x.jsx)(o,{children:`Конфигурацию легко случайно проверить на настоящем data/tasks.json или наследовать значение из локального окружения. Для тестов мы задаём входы явно и направляем storage во временную папку.`}),(0,x.jsx)(`p`,{children:`В изолированной проверке мы подменяем среду и восстанавливаем её после сценария. Отдельный временный JSON показывает, что настройки выбраны как ожидается, а привычный файл не затронут. Если API хранит значения в app.state, fixture возвращает прежние settings и planner после завершения.`}),(0,x.jsx)(`p`,{children:`Мы проверяем не только счастливый путь. Default должен сохранить прежний путь; явные Settings должны пережить сборку; пустое имя и пустой путь должны вызвать понятную ошибку; существующий каталог вместо файла должен быть отклонён до записи. Один и тот же относительный JSON_PATH из корня проекта и из другой cwd должен разрешиться одинаково.`}),(0,x.jsx)(`p`,{children:`Каждый сценарий получает отдельные входы и временный путь. После теста мы возвращаем изменённую среду и состояние API, а затем проверяем выбранный путь повторным чтением через сервис. Так тест доказывает не только значение в Settings, но и то, что рабочие данные не были открыты случайно.`}),(0,x.jsx)(`p`,{children:`Переданный тестовый storage особенно важен: он является явной опорой вызова. Если в build_service передали пустой или временный объект, настройки окружающего процесса не должны заменить его рабочим JsonStorage. Это сохраняет изоляцию и делает результат теста воспроизводимым.`}),(0,x.jsx)(l,{question:`В тест передали временный storage. Что должна выбрать сборка?`,options:[`Переданный объект, потому что его явно указал тест`,`Всегда data/tasks.json из окружения`,`Новый storage на каждый HTTP-запрос`],correctIndex:0,explanation:`Явный объект является выбранной опорой теста. Настройки не должны незаметно заменить его и открыть рабочие данные.`}),(0,x.jsx)(`p`,{children:`После проверки конфигурации мы кратко подтверждаем прежние возможности: API по-прежнему читает и изменяет те же задачи, CLI видит то же состояние, а неправильное тело запроса не записывается. Это регрессия существующего Planner, а не новая реализация CRUD.`})]}),(0,x.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`Мы продолжим существующий Planner: соберём Settings с json_path и app_name, загрузим и проверим значения до использования, затем подключим общую конфигурацию в API и CLI.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Подготовим Settings`,description:`Мы соберём json_path и app_name; отсутствующие значения получат прежние defaults, а пустые остановят загрузку с понятной ошибкой.`},{title:`Подключим API и CLI`,description:`Мы передадим проверенные настройки точкам запуска; API сохранит app.state.settings и прежний app.state.planner.`},{title:`Проверим изоляцию и регрессию`,description:`Мы подтвердим один путь из разных cwd, отказ на пути-каталоге и прежние CRUD, stats и CLI на временных данных.`}]}),(0,x.jsx)(`p`,{children:`Мы применим уже изученную разницу между отсутствием и пустой строкой, а готовыми опорами будут Settings, load_settings, build_service и текущий PlannerService. Проверки направим в отдельные файлы и восстановим переменные окружения и состояние приложения.`}),(0,x.jsx)(`p`,{children:`Результат виден в одном абсолютном пути и успешной работе API и CLI. Неверные значения остановят сборку до записи, переданный тестовый storage останется прежним, а прежние задачи и HTTP-ответы сохранят поведение. Следующий шаг сможет получить уже готовые app.state.settings и app.state.planner через FastAPI-зависимость.`}),(0,x.jsx)(n,{points:[(0,x.jsx)(x.Fragment,{children:`Settings хранит проверенные json_path и app_name, а не загружает их сам.`}),(0,x.jsx)(x.Fragment,{children:`Отсутствие переменной включает default; пустое значение остаётся ошибкой.`}),(0,x.jsx)(x.Fragment,{children:`Относительный путь привязывается к корню проекта, абсолютный не меняется.`}),(0,x.jsx)(x.Fragment,{children:`Конфигурацию собираем на запуске, HTTP 422 оставляем ошибке запроса.`}),(0,x.jsx)(x.Fragment,{children:`API и CLI используют общие правила, один Planner и тот же JSON-контракт.`}),(0,x.jsx)(x.Fragment,{children:`В тесте явно переданный storage не уступает настройкам рабочей среды.`})]}),(0,x.jsx)(u,{text:`Соберём проверенный Settings, подключим его при запуске API и CLI и подтвердим единый путь к JSON на изолированных данных.`})]})]})}export{C as Lesson71};